    Implement fnmatch.fnmatchcase semantics from scratch.
    Supports:
      * - any run of characters (including empty)
      ? - exactly one character
      [seq] - any character in seq
      [!seq] - any character NOT in seq
      ] immediately after [ or [! is a literal ]
      unterminated [ is a literal [
    Match is anchored to the whole string.
    """
    def match_here(pat, pos, name, npos):
        """
        Match pattern starting at pos against name starting at npos.
        Returns True if the rest of pattern matches the rest of name.
        """
        while pos < len(pat):
            c = pat[pos]
            if c == '*':
                # Skip consecutive *
                while pos < len(pat) and pat[pos] == '*':
                    pos += 1
                # Now try to match the rest of pattern at each position in name
                # from npos to len(name)
                for i in range(npos, len(name) + 1):
                    if match_here(pat, pos, name, i):
                        return True
                return False
            elif c == '?':
                if npos >= len(name):
                    return False
                npos += 1
                pos += 1
            elif c == '[':
                # Check for negation
                neg = False
                p = pos + 1
                if p < len(pat) and pat[p] == '!':
                    neg = True
                    p += 1
                # Check if ] is immediately after [ or [!
                if p < len(pat) and pat[p] == ']':
                    # ] is a literal, so we need to find the closing ]
                    # The set includes this literal ]
                    start = p
                    p += 1
                    found_close = False
                    close_pos = -1
                    while p < len(pat):
                        if pat[p] == ']':
                            close_pos = p
                            found_close = True
                            break
                        p += 1
                    if not found_close:
                        # Unterminated [ is a literal [
                        if npos >= len(name):
                            return False
                        if name[npos] != '[':
                            return False
                        npos += 1
                        pos += 1
                        continue
                    # Build the set of characters in the class
                    # The class is pat[start:close_pos]
                    # which includes the literal ] at start
                    class_str = pat[start:close_pos]
                    # Parse the class
                    chars = set()
                    i = 0
                    while i < len(class_str):
                        ch = class_str[i]
                        if i + 2 < len(class_str) and class_str[i + 1] == '-':
                            end_ch = class_str[i + 2]
                            if ch <= end_ch:
                                for code in range(ord(ch), ord(end_ch) + 1):
                                    chars.add(chr(code))
                            i += 3
                        else:
                            chars.add(ch)
                            i += 1
                    # Check if name[npos] is in the set
                    if npos >= len(name):
                        return False
                    matched = name[npos] in chars
                    if neg:
                        matched = not matched
                    if not matched:
                        return False
                    npos += 1
                    pos = close_pos + 1
                else:
                    # Normal case: find the closing ]
                    p = pos + 1
                    if neg:
                        p += 1  # skip the !
                    # Find closing ]
                    close_pos = -1
                    q = p
                    while q < len(pat):
                        if pat[q] == ']':
                            close_pos = q
                            break
                        q += 1
                    if close_pos == -1:
                        # Unterminated [ is a literal [
                        if npos >= len(name):
                            return False
                        if name[npos] != '[':
                            return False
                        npos += 1
                        pos += 1
                        continue
                    # Build the set of characters
                    class_str = pat[p:close_pos]
                    chars = set()
                    i = 0
                    while i < len(class_str):
                        ch = class_str[i]
                        if i + 2 < len(class_str) and class_str[i + 1] == '-':
                            end_ch = class_str[i + 2]
                            if ch <= end_ch:
                                for code in range(ord(ch), ord(end_ch) + 1):
                                    chars.add(chr(code))
                            i += 3
                        else:
                            chars.add(ch)
                            i += 1
